PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE users (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  email TEXT UNIQUE NOT NULL,
  password_hash TEXT NOT NULL,
  role TEXT NOT NULL CHECK(role IN ('USER', 'ADMIN')),
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);
CREATE TABLE user_profiles (
  id TEXT PRIMARY KEY,
  user_id TEXT UNIQUE NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  institution TEXT DEFAULT '',
  department TEXT DEFAULT '',
  country TEXT DEFAULT '',
  phone TEXT DEFAULT '',
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
, clerk_id TEXT DEFAULT '');
CREATE TABLE d1_migrations(
		id         INTEGER PRIMARY KEY AUTOINCREMENT,
		name       TEXT UNIQUE,
		applied_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL
);
CREATE TABLE settings (
  key TEXT PRIMARY KEY,
  value TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS "submissions" (
  id TEXT PRIMARY KEY,
  submission_code TEXT UNIQUE NOT NULL,
  title TEXT NOT NULL,
  abstract TEXT NOT NULL,
  keywords TEXT NOT NULL,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  status TEXT NOT NULL DEFAULT 'SUBMITTED' CHECK(status IN (
    'DRAFT',
    'SUBMITTED',
    'UNDER_REVIEW',
    'REVISION_REQUIRED',
    'ACCEPTED',
    'REJECTED',
    'READY_FOR_REGISTRATION',
    'READY_FOR_CAMERA_READY'
  )),
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  track TEXT DEFAULT '',
  author_name TEXT DEFAULT '',
  author_email TEXT DEFAULT '',
  paper_id TEXT DEFAULT '',
  deleted_at TEXT
, enquired INTEGER NOT NULL DEFAULT 0, no_corrections INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS "authors" (
  id TEXT PRIMARY KEY,
  submission_id TEXT NOT NULL REFERENCES "submissions"(id) ON DELETE CASCADE,
  is_primary INTEGER NOT NULL DEFAULT 0,
  first_name TEXT NOT NULL,
  last_name TEXT NOT NULL,
  phone TEXT DEFAULT '',
  email TEXT DEFAULT '',
  college TEXT DEFAULT '',
  created_at TEXT NOT NULL
);
CREATE TABLE reviewers (
  id TEXT PRIMARY KEY,
  username TEXT UNIQUE NOT NULL,
  name TEXT NOT NULL,
  email TEXT DEFAULT '',
  password_hash TEXT NOT NULL,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS "submission_files" (
  id TEXT PRIMARY KEY,
  submission_id TEXT NOT NULL REFERENCES submissions(id) ON DELETE CASCADE,
  file_type TEXT NOT NULL CHECK(file_type IN ('MANUSCRIPT', 'SUPPORTING', 'PLAGIARISM', 'AI_PLAGIARISM')),
  original_filename TEXT NOT NULL,
  storage_key TEXT NOT NULL,
  mime_type TEXT NOT NULL,
  file_size INTEGER NOT NULL,
  uploaded_at TEXT NOT NULL
);
CREATE TABLE mail_templates (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  subject TEXT NOT NULL,
  body TEXT NOT NULL,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);
CREATE TABLE mail_logs (
  id TEXT PRIMARY KEY,
  submission_id TEXT NOT NULL,
  template_id TEXT,
  recipient_name TEXT NOT NULL,
  recipient_email TEXT NOT NULL,
  paper_title TEXT NOT NULL,
  subject TEXT NOT NULL,
  body TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'queued',
  resend_id TEXT,
  error TEXT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS "reviews" (
  id TEXT PRIMARY KEY,
  submission_id TEXT NOT NULL REFERENCES submissions(id) ON DELETE CASCADE,
  reviewer_id TEXT NOT NULL REFERENCES reviewers(id) ON DELETE CASCADE,
  decision TEXT NOT NULL CHECK(decision IN (
    'ACCEPTED',
    'ACCEPTED_WITH_MINOR_CHANGES',
    'ACCEPTED_WITH_MAJOR_CHANGES',
    'NOT_ACCEPTED'
  )),
  feedback TEXT NOT NULL DEFAULT '',
  resubmitted INTEGER NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  UNIQUE(submission_id, reviewer_id)
);
CREATE TABLE users_bak_20260922(
  id TEXT,
  name TEXT,
  email TEXT,
  password_hash TEXT,
  role TEXT,
  created_at TEXT,
  updated_at TEXT
);
CREATE TABLE submissions_bak_20260922(
  id TEXT,
  submission_code TEXT,
  title TEXT,
  abstract TEXT,
  keywords TEXT,
  user_id TEXT,
  status TEXT,
  created_at TEXT,
  updated_at TEXT,
  track TEXT,
  author_name TEXT,
  author_email TEXT,
  paper_id TEXT,
  deleted_at TEXT,
  enquired INT,
  no_corrections INT
);
DELETE FROM sqlite_sequence;
CREATE INDEX idx_users_email ON users(email);
CREATE INDEX idx_user_profiles_user_id ON user_profiles(user_id);
CREATE INDEX idx_user_profiles_clerk_id ON user_profiles(clerk_id);
CREATE INDEX idx_submissions_user_id ON submissions(user_id);
CREATE INDEX idx_submissions_status ON submissions(status);
CREATE INDEX idx_submissions_created_at ON submissions(created_at);
CREATE INDEX idx_submissions_code ON submissions(submission_code);
CREATE INDEX idx_submissions_deleted_at ON submissions(deleted_at);
CREATE INDEX idx_authors_submission_id ON authors(submission_id);
CREATE INDEX idx_submission_files_submission_id ON submission_files(submission_id);
CREATE INDEX idx_mail_logs_submission ON mail_logs(submission_id);
CREATE INDEX idx_mail_logs_status ON mail_logs(status);
CREATE INDEX idx_reviews_submission_id ON reviews(submission_id);
CREATE INDEX idx_reviews_reviewer_id ON reviews(reviewer_id);
